func (d documentDo) FindInBatch(batchSize int, fc func(tx gen.Dao, batch int) error) (results []*store.Document, err error) {
	buf := make([]*store.Document, 0, batchSize)
	err = d.DO.FindInBatches(&buf, batchSize, func(tx gen.Dao, batch int) error {
		defer func() { results = append(results, buf...) }()
		return fc(tx, batch)
	})
	return results, err
}

